        }
      }
    ]
  },
  {
    "id": "product-wiki-freshness",
    "severity": "advisory",
    "failureMessage": "a wiki that stopped growing silently stops being true — staleness must reach a human even when the unattended growth channel isn't firing",
    "relevantWhen": { "scanningWholeRepo": true },
    "scanFiles": "/^product-wiki\\/.+\\/README\\.md$/",
    "excludeFiles": "/^product-wiki\\/(product-requirements|sample-data)\\//",
    "checkSections": [
      {
        "section": "Growth log",
        "newestDatedBulletWithinDays": {
          "days": 45,
          "what": "newest Growth log entry is {age} days old ({date}) — past the {days}-day freshness window",
          "fix": "run a growth pass (in-session: \"grow the product wiki\") or confirm the scheduler's wiki-growth task is wired; silence via rules: {\"product-wiki-freshness\": \"off\"}"
        }
      }
    ]
  }
]

