        if (a.whenFieldPresent && fieldAt(base, a.whenFieldPresent) === undefined) continue;
        const vars = { path, ...(entryName === null ? {} : { entry: entryName }) };
        const flag = (what, fix, at = path, extraVars = {}) => j.out.push(finding(j.rule, {
