1	// The janitor's sweep over the WORK-ITEM QUEUE (tasks-dispatch DESIGN §11) — the
2	// half of this task that runs where `taskScheduler.dispatch` is `"queue"`.
3	//
4	// It shrinks twice over against the slot-mechanism sweep beside it. The re-arm and
5	// its grace window are GONE: an executor polls on the scheduler run's cron, so a lost label
6	// event is latency and never the only delivery. And the executing-leash reclaim
7	// moved to the SCHEDULER RUN — a deterministic label rule, serialized and hourly, which
8	// recovers a dead executor's item in ~2h instead of ~25h.
9	//
10	// What is left is everything needing judgment or a longer horizon: the dead agent
11	// claim, the stale-ready escalation, the stuck-dependency sweep (comment only —
12	// the item still proceeds by itself the moment its blockers resolve), the
13	// stateless-item repair, and a health review that can now be computed from issues.
14	//
15	// This file is the I/O shell; every verdict is a pure rule in the vendored engine,
16	// so what counts as stale, dead or stuck is decided in exactly one place.
17	
18	import {
19	  staleReadyItems, staleReadyComment, deadAgentItems, deadAgentComment,
20	  stuckBlockedItems, stuckBlockedComment, statelessItems, statelessComment,
21	  periodForTasks,
22	} from '../../../claudinite-tasks/queue/janitor-rules.mjs';
23	import {
24	  QUEUE_LABELS, HANDOFF_MARKER,
25	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION,
26	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
27	  isStatus, isParked,
28	  parseWorkItemBody,
29	} from '../../../claudinite-tasks/queue/work-item.mjs';
30	import { listOpenWorkItems } from '../../../claudinite-tasks/queue/read.mjs';
31	import { ensureLabels, addLabel, removeLabel, comment, listComments, readIssue } from '../../../claudinite-tasks/github.mjs';
32	import { clearStatus } from '../../../claudinite-tasks/queue/apply-status.mjs';
33	
34	export async function sweepQueue(gh, repo, now, { tasks = [], log = console.log } = {}) {
35	  const open = await listOpenWorkItems(gh, repo);
36	  const result = { open: open.length, staleReady: [], deadAgents: [], stuck: [], stateless: [] };
37	
38	  // A `Blocked-by` target need not be a work item, so its state is read directly.
39	  const known = new Map(open.map((i) => [i.number, i.state]));
40	  for (const i of open) {
41	    for (const n of parseWorkItemBody(i.body).blockedBy) {
42	      if (known.has(n)) continue;
43	      const res = await gh(`/repos/${repo}/issues/${n}`);
44	      known.set(n, res.status === 200 ? res.json?.state ?? null : null);
45	    }
46	  }
47	
48	  const stale = staleReadyItems(open, now, { periodFor: periodForTasks(tasks) });
49	  const deadAgents = deadAgentItems(open, now);
50	  const stuck = stuckBlockedItems(open, now, { stateOf: (n) => known.get(n) ?? null });
51	  const stateless = statelessItems(open);
52	
53	  if (stale.length || deadAgents.length || stateless.length) await ensureLabels(gh, repo, QUEUE_LABELS);
54	
55	  // Both labels, as everywhere: the state the machine reads plus what the human is
56	  // being asked for.
57	  const escalate = async (item, body, from, park) => {
58	    await comment(gh, repo, item.number, body);
59	    // Every spelling of the status being left goes: the item may have been filed by
60	    // an engine older than this one, and a swap that named one spelling would leave
61	    // the other standing (`apply-status`). The park that replaces it is ONE label.
62	    if (from) await clearStatus({ removeLabel }, gh, repo, item, from);
63	    await addLabel(gh, repo, item.number, park);
64	  };
65	
66	  for (const item of stale) {
67	    await escalate(item, staleReadyComment(item), STATUS_READY, NEEDS_HUMAN_ACTION);
68	    log(`escalated stale-ready #${item.number} → ${NEEDS_HUMAN_ACTION}`);
69	    result.staleReady.push(item.number);
70	  }
71	  for (const item of deadAgents) {
72	    await escalate(item, deadAgentComment(item, await sessionNote(gh, repo, item)), STATUS_RUNNING_AGENT, NEEDS_HUMAN_DECISION);
73	    log(`reclaimed a dead agent claim on #${item.number} → ${NEEDS_HUMAN_DECISION}`);
74	    result.deadAgents.push(item.number);
75	  }
76	  for (const item of stuck) {
77	    // COMMENT ONLY, deliberately: labels untouched means the item still proceeds
78	    // by itself the moment its blockers resolve, and a human who decides it is
79	    // dead closes it by hand.
80	    const unresolved = parseWorkItemBody(item.body).blockedBy.filter((n) => known.get(n) !== 'closed');
81	    await comment(gh, repo, item.number, stuckBlockedComment(item, unresolved));
82	    log(`surfaced stuck dependency on #${item.number} (blocked by ${unresolved.map((n) => `#${n}`).join(', ')})`);
83	    result.stuck.push(item.number);
84	  }
85	  // CONFIRM BEFORE ACTING, and only here. This rule's premise is that the state it
86	  // is reading is TORN — but a swap in flight is indistinguishable from one that
87	  // tore, and `open` is a snapshot taken seconds earlier. An executor that settles
88	  // an item inside that window gets its finished work parked `needs-human`, which
89	  // is a false triage signal a person then has to read (#1104: #1101 closed
90	  // `task:done` at 12:50:13Z and was escalated at 12:50:21Z). The other three rules
91	  // turn on a clock rather than on a transient, so they need no second read.
92	  for (const item of stateless) {
93	    const fresh = await readIssue(gh, repo, item.number);
94	    if (!fresh || fresh.state !== 'open' || statelessItems([fresh]).length === 0) {
95	      log(`- #${item.number} settled between this sweep's read and its write — left alone`);
96	      continue;
97	    }
98	    await escalate(item, statelessComment(), null, NEEDS_HUMAN_DECISION);
99	    log(`repaired stateless #${item.number} → ${NEEDS_HUMAN_DECISION}`);
100	    result.stateless.push(item.number);
101	  }
102	
103	  // The health review — the queue as its subject, computable entirely from issues.
104	  const converged = new Set([...result.staleReady, ...result.deadAgents, ...result.stateless]);
105	  const count = (status) => open.filter((i) => isStatus(i, status) && !converged.has(i.number)).length;
106	  log(`health: ${result.open} open work item(s) — ${count(STATUS_BLOCKED)} blocked, ${count(STATUS_READY)} ready, `
107	    + `${count(STATUS_RUNNING_EXECUTOR)} executing, ${count(STATUS_RUNNING_AGENT)} with an agent, `
108	    + `${open.filter(isParked).length + converged.size} parked; `
109	    + `this run escalated ${result.staleReady.length} stale, reclaimed ${result.deadAgents.length} dead agent claim(s), `
110	    + `surfaced ${result.stuck.length} stuck dependency(ies), repaired ${result.stateless.length} stateless item(s)`);
111	  return result;
112	}
113	
114	// The hand-off comment names the session, so the escalation can say WHICH one
115	// died rather than merely that one did. Absent (a torn hand-off), the escalation
116	// says less rather than asserting something it does not know.
117	async function sessionNote(gh, repo, item) {
118	  const handoff = (await listComments(gh, repo, item.number))
119	    .filter((c) => (c.body ?? '').includes(HANDOFF_MARKER)).at(-1);
120	  const nonce = handoff?.body?.match(/nonce `([^`]+)`/)?.[1];
121	  return nonce ? `invocation nonce ${nonce}` : null;
122	}
123

