1	// Is this run's diff NARROW — small enough that the asker said, up front, they did
2	// not want to be asked (tasks-dispatch DESIGN §16.11)? The request task's ceiling
3	// allows a merge; THIS is what decides whether one happens, so the call is
4	// arithmetic over the diff rather than the session's opinion of its own work.
5	//
6	// Narrow means every changed file is one of:
7	//   - documentation — a Markdown/text file;
8	//   - a test — a file or directory the repo names as one;
9	//   - comments only — the code either side of the change is identical once the
10	//     comments are stripped;
11	//   - code, in at most ONE directory across the whole diff.
12	//
13	// So a change that edits one module, its tests, a README and a comment in a file
14	// somewhere else is narrow; one that edits code in two directories is not.
15	//
16	// THE LIMIT THAT BOUNDS THE VERDICT: a file `commentOnly` cannot answer for counts
17	// as code, so a comment-only edit in a language the parser does not model parks the
18	// run rather than merging it. That is the safe end, and it is deliberate — the
19	// verdict grants a merge nobody will look at.
20	
21	import { execFileSync } from 'node:child_process';
22	import path from 'node:path';
23	import { COMMENT_CHECKABLE, commentOnly } from '../../../../../engine/checks/helpers/code-scanning.mjs';
24	
25	// Re-exported so this module stays the one place a caller asks about a narrow
26	// diff; the parser and the safe end are the shared helper's.
27	export { COMMENT_CHECKABLE, commentOnly };
28	
29	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
30	
31	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
32	
33	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
34	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
35	// not a test directory; file names are matched on the conventions every ecosystem
36	// here shares.
37	export function classifyPath(file) {
38	  const segments = file.split('/');
39	  const name = segments[segments.length - 1];
40	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
41	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
42	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
43	  return 'code';
44	}
45	
46	// The verdict over a whole diff. `entries` are `{ file, before, after }`, contents
47	// null where the file was added or deleted. Returns the verdict and the WHY —
48	// which files forced it — because a run that parks has to say what it parked over.
49	export function narrowVerdict(entries) {
50	  const codeDirs = new Map();
51	  const kinds = [];
52	  for (const { file, before, after } of entries) {
53	    const kind = classifyPath(file);
54	    if (kind !== 'code') { kinds.push({ file, kind }); continue; }
55	    if (commentOnly(file, before, after)) { kinds.push({ file, kind: 'comments' }); continue; }
56	    const dir = path.dirname(file);
57	    if (!codeDirs.has(dir)) codeDirs.set(dir, []);
58	    codeDirs.get(dir).push(file);
59	    kinds.push({ file, kind: 'code' });
60	  }
61	  const dirs = [...codeDirs.keys()].sort();
62	  return {
63	    narrow: dirs.length <= 1,
64	    codeDirs: dirs,
65	    files: kinds,
66	    why: dirs.length <= 1
67	      ? (dirs.length === 0
68	        ? 'no code changed — documentation, tests and comments only'
69	        : `code changed in one directory (${dirs[0]}), beside documentation, tests and comment-only edits`)
70	      : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`,
71	  };
72	}
73	
74	// --- the CLI ------------------------------------------------------------------
75	
76	// `stderr: ignore` because the ONE expected failure here — `git show` on a path
77	// that does not exist at that ref — is how an added or deleted file answers, and
78	// letting git narrate it once per such file buries the verdict the caller reads.
79	const git = (args, cwd) => execFileSync('git', args, {
80	  cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore'],
81	});
82	
83	// The content of `file` at `ref`, or null when it does not exist there (an added
84	// file) — the same answer a deleted file's "after" gets.
85	function contentAt(ref, file, cwd) {
86	  try {
87	    return git(['show', `${ref}:${file}`], cwd);
88	  } catch {
89	    return null;
90	  }
91	}
92	
93	// The diff this branch carries against `base`, read from the merge base so
