1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { pathToFileURL } from 'node:url';
19	import { isSuspended, readSuspendedNow, suspendedNotice, SUSPEND_ALL_VAR } from './suspend.mjs';
20	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
21	import { renderTaskExec } from '../run-record.mjs';
22	import { swapStatus, clearStatus } from './apply-status.mjs';
23	import {
24	  READY, URGENT, EXECUTING, AGENT, requeueHint,
25	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
26	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
27	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
28	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
29	  parseWorkItemTitle, isWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
30	  LAST_VERDICT_HEADING, lastVerdictLines } from './work-item.mjs';
31	
32	const titleOf = (item) => (item.title ?? '').trim();
33	// An item somebody is executing — the executor holds it, or the agent it handed to
34	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
35	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
36	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
37	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
38	// machine block's first line, so the id comes from the task whose worker path that
39	// is. `pathTo` is that lookup, injected because only the run holds the task set.
40	const taskIdOf = (item, pathTo = () => null) => {
41	  const p = parseWorkItemTitle(item.title);
42	  if (p) return `${p.pack}/${p.task}`;
43	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
44	};
45	
46	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
47	// two skip rules read live at pick time. Random rather than oldest-first because
48	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
49	// a deterministic order lets one unlucky head dominate every run of a chain
50	// (DESIGN §15.20).
51	//
52	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
53	//    item executing or handed to an agent — one task, one execution at a time,
54	//    while a fan-out's distinct qualifiers still parallelize.
55	//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
56	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
57	//    A declined upstream holds nothing back — it has no item at all (a no files
58	//    only a board row, #1115) — and neither does one sitting `needs-human`: a
59	//    broken upstream must not halt its dependents indefinitely.
60	//
61	// `open` is every open work item; `taskAfter(id)` gives a task's declared
62	// upstreams as `<pack>/<task>` ids, and `frequencyOf(id)` that task's declared
63	// frequency at HEAD — which is half of what says whether an item is a standing
64	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
65	// so a test can pin an order the production call deliberately does not have.
66	export function pickOrder(open = [], { taskAfter = () => [], frequencyOf = () => null, random = Math.random, pathTo = () => null } = {}) {
67	  const idOf = (item) => taskIdOf(item, pathTo);
68	  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
69	  const standing = (item) => isStandingItem(item, frequencyOf(idOf(item)));
70	  const liveUpstream = (upstreamId) => open.some((o) =>
71	    idOf(o) === upstreamId && standing(o) && live(o));
72	  // One draw per item, taken once: a comparator that called `random()` per
73	  // comparison would not be a consistent ordering, and `Array.sort` on one is
74	  // free to produce anything at all.
75	  const draw = new Map(open.map((i) => [i.number, random()]));
76	
77	  return open
78	    .filter((i) => isStatus(i, STATUS_READY))
79	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
80	      && running(o)))
81	    .filter((i) => {
82	      if (!standing(i)) return true;
83	      return !taskAfter(idOf(i)).some(liveUpstream);
84	    })
85	    .sort((a, b) =>
86	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
87	      || draw.get(a.number) - draw.get(b.number));
88	}
89	
90	// The claim comment carries WHO and WHEN — the executor id and its run URL —
91	// because executor identity is an unbounded set and must never become a label
92	// (DESIGN §4).
93	export const claimComment = ({ executor, runUrl, at }) =>
94	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
95	
96	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
97	// each an implicit assumption made explicit:
98	//
99	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
100	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
101	//    comment ids are server-assigned and strictly increasing — a total order the
102	//    protocol gets for free. Nothing here compares runner clocks.
103	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
104	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
105	//    and revert leaves one), and arbitrating over all of them makes a dead claim
106	//    outrank every future live claimant — the item then livelocks through reclaim
107	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
108	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
109	//    owner; it can only leave an item with no state label, which the janitor
110	//    repairs.
111	export function claimWinner(comments = []) {
112	  const sorted = [...comments].sort((a, b) => a.id - b.id);
113	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
114	  const claims = sorted
115	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
116	    .filter((c) => !boundary || c.id > boundary.id);
117	  return claims[0] ?? null;
118	}
119	
120	// After WINNING a claim, re-verify the pick filters against live state (F15). The
121	// filters read possibly-stale state, so two executors can pass them simultaneously
122	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
123	// an upstream and its dependent. The per-item lease cannot see that: it protects
124	// one item, not one title. If a conflicting item now holds an EARLIER claim
125	// (comment id — the same arbiter the lease trusts), this executor reverts its own
126	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
127	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null, pathTo = () => null } = {}) {
128	  const idOf = (i) => taskIdOf(i, pathTo);
129	  const standing = (i) => isStandingItem(i, frequencyOf(idOf(i)));
130	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
131	  return others.some((o) => {
132	    if (o.number === item.number) return false;
133	    if (!running(o)) return false;
134	    const conflicting = titleOf(o) === titleOf(item)
135	      || (upstreams.includes(idOf(o)) && standing(o));
136	    return conflicting && o.claimId != null && o.claimId < myClaimId;
137	  });
138	}
139	
140	// The no-go outcome (DESIGN §6.4, as amended by #1115): every decline CLOSES
141	// the item with the reason. The roll — `Not-before` stamped, open-blocked,
142	// waiting out the period — is gone: "asked and declined" lives on the schedule
143	// board, and a scheduled item's next occurrence is the scheduler run's ask at
144	// its next anchor (the closed-at half of the occurrence guard keeps this
145	// period consumed). `standing` marks whether the close should say so.
146	// The `(item, task, schedule, now, reason)` signature is kept — callers and
147	// fielded tests pass all five, and the standing/ad-hoc distinction still
148	// shapes the close's wording.
149	export function noGoPlan(item, task, schedule, now, reason) {
150	  return {
151	    kind: 'close',
152	    outcome: TASK_OBSOLETE,
153	    stateReason: 'not_planned',
154	    reason,
155	    standing: isStandingItem(item, task?.decl?.frequency),
156	  };
157	}
158	
159	// --- the shell ----------------------------------------------------------------
160	
161	const nowIso = () => new Date().toISOString();
162	
163	// ONE EXECUTOR RUN DRAINS THE QUEUE (DESIGN §6, §10, decision §15.30, reversing
164	// §15.22's one-item run). Actions bills each job's runtime rounded UP to the next
165	// minute, so a day's cost is the RUN count: a run that performed one item paid a
166	// whole invocation — checkout, setup, rounding — per item. So a run claims an
167	// item, sees it to its settle, then picks the next, and ends when nothing is
168	// pickable. Items still settle ONE AT A TIME: this moved the run boundary, not
169	// the occupancy model, and capacity is still executor width.
170	//
171	// What still starts a run is the enumerable list of §10, each cause on the
172	// record: the scheduler run's drain job (dispatched only when that run leaves
173	// something pickable), a label event, an agent session's close-time drain, and
174	// the workflow's failure-continuation job when a run dies mid-drain. Self-
175	// re-dispatch retired with the one-item run — the remainder is this run's own.
176	//
177	// AN ITEM THIS RUN LET GO OF IS NEVER RE-ATTEMPTED BY IT. Losing a claim race
178	// leaves the item running under its winner, so the next pick simply does not see
179	// it — but a post-claim REVERT puts the item back to ready, and re-picking what
180	// this run just returned to the queue is an unbounded loop, not a retry. Both
181	// exits are therefore recorded in `standDown` and skipped for the rest of the
182	// run; the executor that won, and the scheduler run behind it, carry those.
183	//
184	// The loop terminates because every iteration either settles an item (which
185	// leaves the ready state) or stands down from one — and the only items that
186	// newly become pickable are the dependents a close releases, which is the
187	// chaining this exists to do. Its outer bound is the workflow's own timeout.
188	//
189	// Injected seams keep the run testable end to end without GitHub, code-work
190	// subprocesses or an invocation endpoint. `heldNow` is the operator hold, asked
191	// between items (§15.30): `vars.*` reaches the env at start only, so a drain that
192	// outlives the hold's arrival can only see it by asking.
193	export async function runExecutor({
194	  gh, repo, root, config, tasks, executorId, runUrl = null,
195	  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
196	  collectSignalsFor, runTaskCodeWork, invokeAgent, heldNow = null, log = console.log,
197	}) {
198	  const api = await import('../github.mjs');
199	  const { listOpenWorkItems } = await import('./read.mjs');
200	  const schedule = config.taskScheduler;
201	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
202	  const taskAfter = (id) => byId.get(id)?.decl?.schedule_after ?? [];
203	  const frequencyOf = (id) => byId.get(id)?.decl?.frequency ?? null;
204	  // A marked issue names its task by worker path, so the run needs the inverse of
205	  // the id map — built from the same task set, so a path this repo does not carry
206	  // resolves to nothing and the item is malformed rather than guessed at.
207	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
208	  const pathTo = (p) => byPath.get(p) ?? null;
209	  const done = [];
210	  // Items this run has let go of — a lost race, a reverted claim — and must not
211	  // pick again. Without it a revert re-picks what it just returned to the queue.
212	  const standDown = new Set();
213	
214	  for (;;) {
215	    // Read live every time: the settle just made may have readied a dependent,
216	    // and another executor may have taken what was pickable a moment ago.
217	    const open = await listOpenWorkItems(gh, repo);
218	    const candidate = pickOrder(open, { taskAfter, frequencyOf, random, pathTo })
219	      .find((i) => !standDown.has(i.number));
220	    if (!candidate) break;
221	
222	    // --- claim: the verified lease ------------------------------------------
223	    await swapStatus(api, gh, repo, candidate, STATUS_READY, EXECUTING);
224	    await api.comment(gh, repo, candidate.number, claimComment({
225	      executor: executorId, runUrl, at: nowIso(),
226	    }));
227	    const comments = await api.listComments(gh, repo, candidate.number);
228	    const winner = claimWinner(comments);
229	    const mine = [...comments]
230	      .sort((a, b) => a.id - b.id)
231	      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
232	      .at(-1);
233	    if (!winner || winner.id !== mine?.id) {
234	      // The loser reverts nothing — the winner's labels already stand. It does
235	      // strike its own claim (F24): letting go covers losing too, and a claim left
236	      // behind here outlives the winner's episode and becomes the earliest of the
237	      // NEXT one, moving the livelock one episode along.
238	      await strikeClaim(api, gh, repo, mine);
239	      standDown.add(candidate.number);
240	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — leaving it to them`);
241	      continue;
242	    }
243	
244	    // --- post-claim re-verify (F15) -----------------------------------------
245	    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
246	    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, frequencyOf, pathTo })) {
247	      await api.comment(gh, repo, candidate.number,
248	        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
249	      await swapStatus(api, gh, repo, candidate, STATUS_RUNNING_EXECUTOR, READY);
250	      standDown.add(candidate.number);
251	      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
252	      continue;
253	    }
254	
255	    const outcome = await executeItem({
256	      api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
257	      claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
258	    });
259	    done.push({ issue: candidate.number, outcome });
260	
261	    // --- the hold, between items (§15.30) -----------------------------------
262	    // Asked after the settle rather than before the pick that follows it, so a
263	    // run that had nothing more to do never spends the read. The item just
264	    // finished is untouched: suspension stops picking, never running work.
265	    if (heldNow && await heldNow()) {
266	      log(`- ${SUSPEND_ALL_VAR} is set: this drain stops here, holding nothing. Items stay exactly as they are.`);
267	      break;
268	    }
269	  }
270	  return done;
271	}
272	
273	// The claim id of each live item, so the post-claim verify can compare episodes.
274	// One comment read per conflicting-looking item, not per item in the repo.
275	async function withClaimIds(api, gh, repo, items, selfNumber) {
276	  const out = [];
277	  for (const i of items) {
278	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
279	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
280	    out.push({ ...i, claimId: winner?.id ?? null });
281	  }
282	  return out;
283	}
284	
285	// One claimed item, from validation through to a terminal state (or a hand-off).
286	async function executeItem({
287	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
288	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
289	}) {
290	  const parsed = parseWorkItemTitle(item.title);
291	  const { taskPath } = parseWorkItemBody(item.body);
292	  // A marked issue's identity is its machine block, not its title (§16.1): the id
293	  // is whichever task owns the worker path the block names.
294	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
295	  const task = id ? byId.get(id) : null;
296	  // The exec record joins back to the work by pack and task, which a marked issue's
297	  // human title cannot supply — so the resolved id travels with the item.
298	  item.taskId = id;
299	
300	  // --- validate in code, before anything trusts the issue ------------------
301	  if (!taskPath || (!parsed && !id)) {
302	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
303	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
304	    return 'needs-human';
305	  }
306	  if (!task) {
307	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
308	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone');
309	    return 'obsolete';
310	  }
311	  if (task.taskPath !== taskPath) {
312	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
313	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
314	    return 'needs-human';
315	  }
316	
317	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
318	  const at = now();
319	  const fields = parseWorkItemBody(item.body);
320	  // The signals are collected FOR THIS OCCURRENCE, and the precondition judges over
321	  // it: a request item's verdict is about the issue it names, which no signal bundle
322	  // can single out on its own (DESIGN §16.4).
323	  const signals = await collectSignalsFor(task, at, item);
324	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields);
325	
326	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
327	  // decline is a decision about the world; one taken on an API that would not answer
328	  // is a guess, and its write-backs cannot land — for a request that would strand
329	  // the issue armed-but-queued forever, the request silently eaten. So the item
330	  // parks open in the failure lane, where the ordinary re-queue lever retries it
331	  // once the API recovers, and nothing is written to whatever it could not read.
332	  if (verdict.error) {
333	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
334	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
335	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
336	    return 'needs-human';
337	  }
338	
339	  if (verdict.run !== true) {
340	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
341	    // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (DESIGN §16.5).
342	    // Nothing else would: an issue left carrying `claude-queued` after its run was
343	    // refused is one no later scheduler run adopts and no person is told about, and one
344	    // whose mark — if re-applied — walks into the same refusal forever.
345	    // A LEGACY shadow item wrote its decline back to the issue it named. A marked
346	    // issue IS the item, so the decline's comment and its `rejected` status already
347	    // land where the person is looking and there is nothing to mirror (§16.5).
348	    if (fields.request && fields.request !== item.number) {
349	      await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
350	    }
351	    // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
352	    // no, and closed the occurrence — so the record says `success` and the
353	    // reason sits beside it in the same comment.
354	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
355	      `The precondition declined: ${plan.reason}`
356	      + (plan.standing
357	        ? '\n\nThis task\'s next occurrence is decided at its next anchor; declined occurrences are recorded on the schedule board.'
358	        : ''), 'success');
359	    return 'obsolete';
360	  }
361	
362	  // --- code-work (unchanged contract), then converge or hand off -------------
363	  // The item's OWN Context is scope too, not decoration: an operator's parameters
364	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
365	  // so code-work sees the union of what the item was created with and what this
366	  // occurrence's precondition added. Passing only the verdict's half is what made
367	  // a hand-created item's parameters unreachable (#974).
368	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
369	  if (task.decl.code_work) {
370	    // The work step may legitimately run for hours (§15.15). While it does, the
371	    // item's only sign of life is this beat — which is also what the scheduler run's leash
372	    // measures, so a long run is legal rather than reclaimed underneath itself.
373	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context }), {
374	      intervalMs: heartbeatMs,
375	      log,
376	      beat: (minutes) => api.comment(gh, repo, item.number,
377	        heartbeatComment({ executor: executorId, at: nowIso(), minutes })),
378	    });
379	    if (!result.ok) {
380	      // The worker's own verdict routes the park where it left one; a worker that
381	      // said nothing about why it failed is a `failure` — the lane that means
382	      // "someone reads the trace", which is the only safe default for a run whose
383	      // cause is unknown.
384	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, triageLabelFor(result.triage?.kind), claim,
385	        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
386	        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
387	      return 'needs-human';
388	    }
389	    if (result.missingSecrets?.length) {
390	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_ACTION, claim,
391	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (${requeueHint}).`);
392	      return 'needs-human';
393	    }
394	    if (!result.agentRequested) {
395	      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
396	      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
397	      // than closing as delivered. It does not hold the task's lane while it waits
398	      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
399	      // an unreviewed PR delays nobody but its reviewer.
400	      if (result.openPr) {
401	        await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_APPROVAL, claim,
402	          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
403	          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`, null);
404	        return 'needs-human';
405	      }
406	      await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_DONE, 'completed',
407	        result.delivered?.length
408	          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
409	          : 'Code-work did this run\'s work; no agent was needed.', 'success');
410	      return TASK_DONE;
411	    }
412	    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
413	  }
414	
415	  // An agentless task with no code-work does nothing (the contract forbids it).
416	  if (task.decl.agent_model === 'none') {
417	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
418	      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.', 'invalid');
419	    return 'needs-human';
420	  }
421	  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
422	}
423	
424	// Run one task's precondition. THE only place a precondition is ever called, so a
425	// test that drives this drives what production drives — a precondition first
426	// written to take `{ signals }` passed its own direct-call test and threw on every
427	// real run, which is the failure this seam exists to make impossible.
428	//
429	// A throwing precondition converges to a no-go with the error as its reason: one
430	// task's bad verdict is that item's problem, never the executor's.
431	export function evaluatePrecondition(task, signals, packConfig = {}, item = null) {
432	  try {
433	    return task.decl.precondition(signals, packConfig, item) ?? {};
434	  } catch (e) {
435	    return { run: false, reason: `precondition threw: ${e.message}` };
436	  }
437	}
438	
439	// @deprecated The write-back a refused SHADOW item's issue got — one comment saying
440	// why, and the queued label off, so the request was disarmed rather than left
441	// looking pending. Nothing writes it for an item filed under the one-issue model,
442	// where the item and the issue are the same object; it stays for the shadow items
443	// still draining, whose issue is a different one (DESIGN §16.5).
444	async function declineRequest(api, gh, repo, request, item, reason) {
445	  await api.comment(gh, repo, request,
446	    `Not implementing this: ${reason}\n\nThe queued run (#${item}) is closed and \`${QUEUED_LABEL}\` is removed. `
447	    + 'If this was wrong, mark the issue again — a request is only run when the person who opened it, or somebody who commented `/claude go`, has push access here.');
448	  await api.removeLabel(gh, repo, request, QUEUED_LABEL);
449	}
450	
451	// @deprecated The roll retired with #1115 — nothing writes this any more. Kept
452	// exported because bodies the fielded roll wrote are stored data: the
453	// round-trip test over this writer is what pins `parseLastVerdict`'s decode,
454	// which the migration and the dashboard still read.
455	export function rollBody(body, until, reason, at) {
456	  const stamped = withNotBefore(body, until);
457	  return withSection(stamped, LAST_VERDICT_HEADING, lastVerdictLines({ at, reason, until }));
458	}
459	
460	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
461	// what lets this be as short as it is. The nonce goes on the item before the call
462	// and travels in the payload, so the session can prove the fire it arrived on is
463	// the hand-off this item recorded and stop if it is not.
464	async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
465	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
466	  // Every section lands in the machine's half of the body — the whole body for a
467	  // filed item, the machine block for a marked issue, whose prose is the person's.
468	  const body = editItemBody(item.body, (machine) => {
469	    let out = machine;
470	    if (context.length) out = withSection(out, 'Context', context);
471	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
472	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
473	    return out;
474	  });
475	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
476	
477	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
478	  await api.comment(gh, repo, item.number,
479	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
480	
481	  const invocation = await invokeAgent({ task, item, nonce, config });
482	  if (invocation.ok) {
483	    await api.comment(gh, repo, item.number,
484	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
485	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
486	    return 'agent';
487	  }
488	  if (invocation.answered) {
489	    // The endpoint refused, so no session exists and none will: a token, a URL or
490	    // a routine is wrong, and every future pick would be refused the same way.
491	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
492	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (${requeueHint}).`);
493	    return 'needs-human';
494	  }
495	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
496	  // may have started a session. Re-queueing here is what would put two sessions on
497	  // one item, and converging to triage would kill a run that is very possibly
498	  // alive. So the item STAYS with the agent and says the outcome is unknown —
499	  // whichever way it went is then settled by a rule that already exists: a session
500	  // that started converges the item, and one that never did leaves the item silent
501	  // until the janitor's agent leash sweeps it to triage.
502	  await api.comment(gh, repo, item.number,
503	    `The agent invocation got no answer: ${invocation.error}\n\n`
504	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
505	    + 'If a session did start it will converge this item; if it did not, the janitor\'s agent leash parks it for a human within a few hours.');
506	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
507	  return 'unknown';
508	}
509	
510	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
511	// that stops owning an item without closing it — the roll, and every
512	// `needs-human` park — strikes its own claim by appending the episode marker to
513	// it. `claimWinner` already treats the last marker as the boundary, so a struck
514	// claim stops outranking anything and the next claimant wins on its first try.
515	//
516	// APPENDING rather than commenting is what lets the roll stay silent (§5): an
517	// hourly task that declines every hour adds no timeline entry. A successful
518	// hand-off deliberately does NOT strike — the episode is still live, owned by the
519	// agent session — and neither does a close, since nothing re-claims a closed item.
520	//
521	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
522	// executor that dies between the two leaves the item `task:executing` with a
523	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
524	// would leave exactly the state this fixes — parked, re-queued by a human, and
525	// unclaimable forever.
526	async function strikeClaim(api, gh, repo, claim) {
527	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
528	  await api.editComment(gh, repo, claim.id,
529	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
530	}
531	
532	// Every exit converges the item exactly once, with one comment saying what
533	// happened — the terminal-state discipline the incidents bought. The claim sits
534	// before the body so every state argument is grouped ahead of the prose.
535	//
536	// THE COMMENT CARRIES THE EXECUTION RECORD (DESIGN §6.5, §15.18). Actions logs
537	// expire, and for an agentless run — the majority — the item is the only durable
538	// trace there will ever be, so the record goes where the item is rather than into
539	// a log that ages out. The bracketed field is this item's issue number, which is
540	// the only join from a record back to the work it describes.
541	// A status of `null` writes NO record, and that is the honest answer for a park
542	// that is not a failure: the vocabulary's `success` means "ran to completion and
543	// the issue was closed" and `failed` means the run broke, so an approval park —
544	// a run that succeeded and left a PR for a person — is neither. Absence is a
545	// state of its own; inventing a fifth status is a change to stored data every
546	// decoder in the fleet would have to learn.
547	const recordFor = (item, status) => {
548	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
549	  // title parse alone would silently drop the record for every request run.
550	  const id = item.taskId ?? null;
551	  const parsed = status
552	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
553	    : null;
554	  return parsed
555	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
556	    : '';
557	};
558	
559	// Park an item for a human. ONE label: the park IS the status, and its kind is what
560	// the human is being asked for (DESIGN §4). The two-label park it replaces could be
561	// half-applied, which was a torn state of its own.
562	async function converge(api, gh, repo, item, from, park, claim, body, status = 'failed') {
563	  await strikeClaim(api, gh, repo, claim);
564	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
565	  await swapStatus(api, gh, repo, item, from, park);
566	}
567	
568	// A close writes only to the item it holds (§15.19, reversed by §15.31 /
569	// #1373): a dependent this close may make due is released solely by the
570	// scheduler run's own readiness job, on its next hourly pass, never here.
571	async function close(api, gh, repo, item, from, outcome, stateReason, body, status) {
572	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
573	  await clearStatus(api, gh, repo, item, from);
574	  await api.addLabel(gh, repo, item.number, outcome);
575	  // A MARKED ISSUE IS NOT THE RUN'S TO CLOSE (§16.1, §16.5). The item's terminal
576	  // status stands on the still-open issue: the run's verdict is about the run, and
577	  // whether the issue is finished belongs to the person who opened it.
578	  if (!isWorkItemTitle(item.title)) return;
579	  await api.closeIssue(gh, repo, item.number, stateReason);
580	}
581	
582	// --- CLI ----------------------------------------------------------------------
583	
584	async function main() {
585	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
586	  // first API call, so a held queue reads nothing and writes nothing rather than
587	  // deriving the world and then declining to act on it.
588	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
589	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
590	  const { discoverTasks } = await import('../discover.mjs');
591	  const { loadConfig, isDormant } = await import('../../../engine/checks/helpers/repo-context.mjs');
592	  const { ensureLabels } = await import('../github.mjs');
593	  const { collectSignalsForTask } = await import('./signals.mjs');
594	  const { codeWorkRunner } = await import('./code-work-run.mjs');
595	  const { agentInvoker } = await import('./invoke.mjs');
596	
597	  const root = process.cwd();
598	  const { repo, defaultBranch } = actionRepoContext();
599	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
600	  const config = loadConfig(root);
601	
602	  console.log('## Claudinite executor\n');
603	  if (isDormant(config)) {
604	    console.log('- this project declares itself dormant — nothing is picked up');
605	    return;
606	  }
607	
608	  const gh = makeGh();
609	  const { tasks, errors } = await discoverTasks(root, config);
610	  for (const e of errors) console.log(`! ${e.what}`);
611	  await ensureLabels(gh, repo, QUEUE_LABELS);
612	
613	  const runUrl = process.env.GITHUB_RUN_ID
614	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
615	    : null;
616	
617	  const done = await runExecutor({
618	    gh, repo, root, config, tasks,
619	    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
620	    runUrl,
621	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
622	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
623	    invokeAgent: agentInvoker({ repo, config }),
624	    heldNow: () => readSuspendedNow(gh, repo, { log: console.log }),
625	  });
626	
627	  console.log(done.length
628	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
629	    : '- nothing ready to pick up');
630	}
631	
632	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
633	  main().catch((e) => { console.error(e); process.exit(1); });
634	}
635

