1	// The generator's scheduler run (tasks-dispatch DESIGN §5) — the whole of the
2	// queue's scheduled machinery: it decides at the anchor and files an issue
3	// only when there is work (#1115, decision §15.28).
4	//
5	// Four jobs: INSTANTIATE — when a recurring task's anchor comes, evaluate its
6	// precondition through the injectable `evaluate` seam and create the work
7	// item only on a yes (a no is a row on the schedule board; a read the
8	// scheduler cannot make fails OPEN and creates the item for the executor to
9	// decide); READY blocked items whose dependencies have resolved and whose
10	// not-before has passed; ADOPT the issues somebody marked for implementation;
11	// and RECLAIM dead executor claims. The executor still re-evaluates at pick
12	// (§6.4) — the board's verdict is a watermark, never a verdict carried
13	// forward. A task's FIRST window is a row too (#1215): first sight books it and
14	// files nothing, so adopting a task costs no open issue. Beside job 1, two
15	// sweeps: a one-time migration retiring the sleeping standing items both
16	// earlier models left open, and the reap of a standing item whose task is no
17	// longer declared at HEAD.
18	//
19	// The run's last act is the DRAIN GATE (§15.30): it reports whether it left
20	// anything pickable, and the workflow's drain job starts an executor only then —
21	// an idle hour costs this one run rather than two.
22	//
23	// `planSchedulerRun` is the decision core, kept injectable so it tests with fixtures; the
24	// CLI shell below wires the GitHub reads, the signal-collection seam, and applies the ops.
25	
26	import { pathToFileURL } from 'node:url';
27	import { isSuspended, suspendedNotice } from './suspend.mjs';
28	import { mostRecentAnchor, nextAnchor } from './anchors.mjs';
29	import { EXECUTING_LEASH_MS } from './leases.mjs';
30	import { swapStatus } from './apply-status.mjs';
31	import { isReleasable } from './readiness.mjs';
32	import { pickOrder } from './executor.mjs';
33	import { lastLivenessAt } from './heartbeat.mjs';
34	import {
35	  WORK_PREFIX, BLOCKED, READY, TASK_OBSOLETE,
36	  NEEDS_HUMAN_DECISION, isBlockingPark,
37	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
38	  isStatus, isParked, statusOf,
39	  QUEUE_LABELS, EPISODE_MARKER, workItemTitle, parseWorkItemTitle, parseWorkItemBody,
40	  workItemBody, labelNames, hasLabel, parseLastVerdict,
41	  ORIGIN_AD_HOC, ORIGIN_PLANNED, ORIGIN_LABELS, REQUEST_LABEL, parseRequestFields,
42	  parseBlockedBy, withMachineBlock,
43	} from './work-item.mjs';
44	import { VERDICT_NO, VERDICT_GO, VERDICT_FAIL_OPEN, SCHEDULE_PREFIX } from './schedule-board.mjs';
45	import { REQUEST_TASK_ID } from '../built-in-tasks.mjs';
46	
47	// The scheduler run owns the executing-leash reclaim because it is deterministic and
48	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
49	// ~25h (DESIGN §11, owner decision 6).
50	export { EXECUTING_LEASH_MS };
51	
52	const ms = (t) => (t == null ? null : new Date(t).getTime());
53	
54	// What a board row says for a task whose first window has not come: the reason
55	// column IS the whole record of the wait, so it names the instant being waited
56	// for — the one thing the born-blocked item it replaces carried.
57	const firstWindowReason = (window) => `first window at ${window} — a task is never run off-anchor on the repo that has just adopted it`;
58	
59	// The ops `planSchedulerRun` emits, each a label-and-body mechanic the shell applies:
60	//   { kind: 'dedupe',  issue, reason }            close, task:obsolete
61	//   { kind: 'create',  pack, task, labels, body } a task's standing item
62	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
63	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
64	//   { kind: 'adopt',   request, title, body, … }  a marked issue becomes an item
65	//   { kind: 'supersede', issue, request, reason } a parked prior run of a re-ask
66	//   { kind: 'retire-sleeping', issue, reason }    migration: a sleeping standing item closes
67	//   { kind: 'retire-orphan', issue, reason }      a standing item whose task is gone closes
68	//   { kind: 'board',   rows }                     rewrite the schedule board (rows changed)
69	//
70	// `items` is every `[claudinite-work]` issue the shell fetched (state=all for the
71	// scheduled families, open for the rest), each `{ number, title, body, state,
72	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
73	// state of a `Blocked-by` target that may not be a work item at all; an unknown
74	// number is never treated as closed, so an unreadable blocker delays rather than
75	// releases (the convergence-not-prevention posture).
76	//
77	// `evaluate(task)` is the anchor-side ask (#1115): async, returning the
78	// precondition's verdict `{ run, reason, … }` or `{ error }` where the
79	// scheduler could not decide — a missing credential, a failed signal read, a
80	// throwing precondition. An error FAILS OPEN: the item is created exactly as
81	// the calendar-only model created it and the executor decides at pick. With
82	// no seam wired (`evaluate: null` — a fixture, or an older shell) every
83	// occurrence fails open the same way, which IS the old behaviour.
84	//
85	// `board` is the parsed schedule board: `{ rows: Map<taskKey, row> }` (see
86	// schedule-board.mjs), or null where it could not be read — which reads as
87	// absent and evaluates. Only a row whose verdict is `no` and whose lastAsked
88	// equals the current anchor suppresses a re-ask (F31).
89	export async function planSchedulerRun({
90	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
91	  stateOf = () => null, evaluate = null, board = null,
92	}) {
93	  const nowMs = ms(now);
94	  const ops = [];
95	  const closedByThisRun = new Set();
96	  const boardRows = new Map(board?.rows ?? []);
97	  let boardChanged = false;
98	  const writeRow = (key, frequency, lastAsked, verdict, reason) => {
99	    const prev = boardRows.get(key);
100	    // Only the authoritative columns count as change; the next-window column
101	    // is derived at render time and must never cause a rewrite by itself.
102	    if (prev && prev.lastAsked === lastAsked && prev.verdict === verdict && (prev.reason ?? '') === (reason ?? '')) return;
103	    boardRows.set(key, { task: key, frequency, lastAsked, verdict, reason: reason ?? '' });
104	    boardChanged = true;
105	  };
106	
107	  // ---- the one-time migration (#1115, #1215), and the orphan reap -------
108	  // A sleeping standing item — open, blocked, unqualified, a FUTURE Not-before,
109	  // no blockers — closes with its window seeded onto the board, whether it was
110	  // ROLLED there by the retired roll model (a `Last verdict` section says so, and
111	  // its own reason is what the row carries) or BORN blocked at adoption (no such
112	  // section: the row says which window it is waiting for). Either way the fact it
113	  // held open — "not now, next ask at X" — is what the board is for, and holding
114	  // an issue open to say it is the cost #1115 set out to remove.
115	  //
116	  // Idempotent: closed items never match again, and a seeded row is written only
117	  // where none exists. Untouched: items waiting on a blocker, which are somebody's
118	  // dependency rather than a window.
119	  //
120	  // Beside it, the orphan reap: a standing item whose `<pack>/<task>` is not
121	  // declared at HEAD can never execute — job 1 matches its family title-exact on
122	  // the declared id, so a legacy pack spelling is invisible to it, and job 2 would
123	  // otherwise ready the item at its Not-before and hand an executor a task path
124	  // that is not on disk. Guarded on a non-empty task list so an unreadable
125	  // declaration reaps nothing, and scoped to BLOCKED so nothing in flight is
126	  // touched — a ready orphan is picked within the hour and parks for a human,
127	  // which is visible rather than silent.
128	  //
129	  // Both are gated on the evaluation seam being wired, so a fixture driving the
130	  // calendar-only shape sees neither.
131	  if (evaluate) {
132	    const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
133	    for (const item of items) {
134	      if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) continue;
135	      const parsed = parseWorkItemTitle(item.title);
136	      if (!parsed || parsed.qualifier !== null) continue;
137	      const key = `${parsed.pack}/${parsed.task}`;
138	      const { notBefore, blockedBy } = parseWorkItemBody(item.body);
139	      if (blockedBy.length) continue;
140	
141	      if (!byId.has(key)) {
142	        if (!tasks.length) continue;
143	        closedByThisRun.add(item.number);
144	        ops.push({
145	          kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
146	          reason: `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
147	            + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
148	        });
149	        continue;
150	      }
151	
152	      const freq = byId.get(key).decl?.frequency ?? null;
153	      if (freq == null || freq === 'manual') continue; // not a standing item
154	      if (!notBefore || (ms(notBefore) ?? -Infinity) <= nowMs) continue;
155	      const verdict = parseLastVerdict(item.body);
156	      if (!boardRows.has(key)) {
157	        writeRow(key, freq,
158	          verdict?.at ?? mostRecentAnchor(freq, schedule, now).toISOString(),
159	          VERDICT_NO, verdict ? (verdict.reason ?? '') : firstWindowReason(notBefore));
160	      }
161	      closedByThisRun.add(item.number);
162	      ops.push({
163	        kind: 'retire-sleeping', issue: item.number, pack: parsed.pack, task: parsed.task,
164	        reason: verdict
165	          ? 'Closing: a declined occurrence now lives as a row on the schedule board '
166	            + `(\`${SCHEDULE_PREFIX}\`), not as a sleeping work item. The next ask happens at this task's next anchor.`
167	          : "Closing: a task's first window is now a row on the schedule board "
168	            + `(\`${SCHEDULE_PREFIX}\`), not an item held open until its anchor. The first ask happens at that anchor.`,
169	      });
170	    }
171	  }
172	
173	  // ---- job 1: instantiate — evaluate at the anchor; a yes files the item ----
174	  for (const task of tasks) {
175	    if (task.decl.frequency === 'manual') continue;
176	    const key = `${task.pack}/${task.id}`;
177	    const title = workItemTitle({ pack: task.pack, task: task.id });
178	    // The family is title-EXACT, which is also what makes it STRUCTURALLY the
179	    // standing family (§15.26): this task is on a calendar and the title carries no
180	    // qualifier, so a fan-out target or a request — qualified, both of them — is a
181	    // different title and neither suppresses nor consumes an occurrence (§3).
182	    const family = items.filter((i) => (i.title ?? '').trim() === title);
183	    // A park that is somebody's INBOX rather than a fault — a PR to approve, a
184	    // choice to make, a secret to set — does not hold the lane: it is neither this
185	    // task's standing item nor a duplicate of it, so it drops out here entirely and
186	    // the schedule goes on around it. A `failure` park (and any park an older engine
187	    // left unclassified) stays in, and holding the lane is the point.
188	    const open = family
189	      .filter((i) => i.state === 'open' && !closedByThisRun.has(i.number))
190	      .filter((i) => !isParked(i) || isBlockingPark(i))
191	      .sort((a, b) => a.number - b.number);
192	
193	    // F16 self-heal, FIRST: nothing documents that a REST list from another node
194	    // sees a creation seconds old, so a stale list can let a duplicate standing
195	    // item through. Assume it will happen rather than that it won't — close every
196	    // open family item but the oldest. Serialized by the scheduler run's concurrency group,
197	    // so this can never race itself.
198	    for (const dup of open.slice(1)) {
199	      closedByThisRun.add(dup.number);
200	      ops.push({
201	        kind: 'dedupe', issue: dup.number, pack: task.pack, task: task.id,
202	        reason: `a duplicate standing item for ${task.pack}/${task.id} — #${open[0].number} is this task's standing item`,
203	      });
204	    }
205	    if (open.length) continue; // the standing item already exists
206	
207	    const anchor = mostRecentAnchor(task.decl.frequency, schedule, now);
208	    const anchorMs = anchor.getTime();
209	    // The occurrence guard has TWO halves (F13): an item CREATED at-or-after the
210	    // anchor covers this occurrence — and so does an item CLOSED at-or-after it,
211	    // because an item created in an earlier period that ran and closed today
212	    // consumed today's occurrence. With the created_at half alone, the very next
213	    // scheduler run after such a close creates a second item for the same occurrence: a
214	    // double execution. An item this very run retired counts as closed now.
215	    const covered = family.some((i) =>
216	      (ms(i.created_at) ?? -Infinity) >= anchorMs
217	      || (ms(i.closed_at) ?? -Infinity) >= anchorMs
218	      || closedByThisRun.has(i.number));
219	    if (covered) continue;
220	
221	    // FIRST SIGHT of a task on this repo: it must not run off-anchor on the
222	    // least-proven repo (S25), and under "no work, no item" that wait is a board
223	    // row rather than an item held open until the anchor (#1215). The board is
224	    // half of what makes it first sight — an item this task once had is the other
225	    // half, and either one alone would re-book the window forever.
226	    //
227	    // The cost, stated: for a task that has never yet run, a board deleted mid-
228	    // window reads as first sight again and costs one skipped occurrence, where
229	    // the board's own header promises one redundant evaluation. Past a task's
230	    // first run its family is non-empty forever and that promise holds again.
231	    const firstEver = family.length === 0 && !boardRows.has(key);
232	    if (evaluate) {
233	      // The watermark: this anchor was already asked and DECLINED. Scoped to
234	      // declined rows only (F31, and see schedule-board.mjs): a go/fail-open
235	      // verdict's cover is the item it created, judged by the guards above.
236	      const row = boardRows.get(key);
237	      if (row && row.verdict === VERDICT_NO && (ms(row.lastAsked) ?? NaN) === anchorMs) continue;
238	
239	      if (firstEver) {
240	        // Booked against the anchor it is declining, so the watermark above holds
241	        // the rest of this window and the first real ask happens at the next one.
242	        writeRow(key, task.decl.frequency, anchor.toISOString(), VERDICT_NO,
243	          firstWindowReason(nextAnchor(task.decl.frequency, schedule, now).toISOString()));
244	        continue;
245	      }
246	
247	      const verdict = (await evaluate(task)) ?? {};
248	      const lastAsked = anchor.toISOString();
249	      if (verdict.error) {
250	        // Fail open: never fewer runs because a read failed — the executor,
251	        // which holds the credentials, decides at pick (§6.4).
252	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_FAIL_OPEN, verdict.error);
253	      } else if (verdict.run !== true) {
254	        // No work, no item: the row is the whole record of this occurrence.
255	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_NO, verdict.reason || 'no work');
256	        continue;
257	      } else {
258	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_GO, verdict.reason || '');
259	      }
260	    }
261	    // Reachable with a first sight only where no seam is wired (a fixture, an
262	    // older shell): there the calendar-only model's born-blocked item is still
263	    // the whole of the off-anchor guard.
264	    const notBefore = firstEver ? nextAnchor(task.decl.frequency, schedule, now).toISOString() : null;
