269	      labels: [ORIGIN_PLANNED, firstEver ? BLOCKED : READY],
270	      body: workItemBody({
271	        taskPath: task.taskPath,
272	        notBefore,
273	        context: firstEver
274	          ? [`This task's first work item on this repo — born blocked until its first real anchor (${notBefore}), so adoption never runs it off-anchor.`]
