310	    const marked = hasLabel(req, ORIGIN_AD_HOC) || hasLabel(req, REQUEST_LABEL);
311	    if (req.state !== 'open' || !marked || statusOf(req) !== null) continue;
312	
313	    // The parameters ride the person's own text, re-read and re-gated at every
314	    // adoption (§16.7): the body is author-editable where a label was
315	    // platform-write-gated, so `Task:`, `Model:` and `Automerge:` are honoured only
316	    // for an author who holds push access. An ungated ask still runs — at the
317	    // default task and model, and authorized to land nothing.
318	    const asked = parseRequestFields(req.body, { gated: req.authorHasPush === true });
