320	    if (!task) continue;
321	    // WHAT THE REQUEST WAITS ON (§16.11). A marked issue may name its blockers in
322	    // the same `Blocked-by:` field an item uses, which is how a follow-up filed
323	    // mid-session queues BEHIND the work in flight instead of racing it. A blocker
324	    // already closed holds nothing back — it is dropped here rather than carried and
325	    // immediately released. `Not-before:` rides the same rule, for the item's other
326	    // wait field: a deferred request waits on a moment as well as on an issue.
327	    const blockedBy = asked.blockedBy.filter((n) => stateOf(n) !== 'closed');
328	    const notBefore = asked.notBefore && ms(asked.notBefore) > nowMs ? asked.notBefore : null;
