330	      kind: 'adopt',
331	      request: req.number,
332	      task: `${task.pack}/${task.id}`,
333	      status: blockedBy.length || notBefore ? BLOCKED : READY,
334	      // The block is the machine's half of a body the human owns and keeps editing,
335	      // so it is written whole here and rewritten in place after that.
