345	      model: asked.model,
346	      blockedBy,
347	      notBefore,
348	      merge: asked.merge,
349	      ungated: asked.ungated,
350	      // Origins are for life (§3), so an issue marked with the retired spelling gains
351	      // the one it will be read by. Nothing removes the old label: it is stored data.
352	      origin: hasLabel(req, ORIGIN_AD_HOC) ? null : ORIGIN_AD_HOC,
353	    });
