355	
356	  // ---- job 3: reclaim dead executor claims (DESIGN §11) -------------------
357	  const policyOf = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t.decl.on_interrupt ?? 'requeue']));
358	  for (const item of items) {
359	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
360	    // SILENCE IS THE HOLDER'S, not the issue's (§11, #924). `updated_at` moves on
361	    // any comment — including the one an executor that LOST the claim race writes
362	    // on its way out — which defers the reclaim of an item nobody is working on.
363	    // `livenessAt` is the shell's read of the holder's last claim or heartbeat;
364	    // where it could not be read, the issue's own clock is the fallback, which is
365	    // the pre-heartbeat behaviour and errs toward waiting.
366	    const lastSign = ms(item.livenessAt) ?? ms(item.updated_at) ?? ms(item.created_at) ?? nowMs;
367	    const silentFor = nowMs - lastSign;
368	    if (silentFor < executingLeashMs) continue;
369	    const parsed = parseWorkItemTitle(item.title);
370	    const minutes = Math.round(executingLeashMs / 60e3);
371	    // `on_interrupt: 'needs-human'` is the at-most-once dial: a task that cannot
372	    // promise a safe re-run is not re-queued by a recovery path — it goes to a
373	    // human, who decides whether the interrupted run left anything behind.
374	    const oneShot = parsed && policyOf.get(`${parsed.pack}/${parsed.task}`) === 'needs-human';
