377	      // what the human is being asked for — whether the interrupted run left
378	      // anything behind, and so whether this re-queues at all.
379	      kind: 'reclaim', issue: item.number, to: oneShot ? NEEDS_HUMAN_DECISION : READY,
380	      reason: oneShot
