384	  }
385	
386	  // ---- the board write, LAST and only on change ---------------------------
387	  // A run that moved no row writes nothing — record changes, never scans —
388	  // and the board is created lazily: the first row that needs writing is
389	  // what mints the issue.
390	  if (boardChanged) ops.push({ kind: 'board', rows: [...boardRows.values()] });
391	
392	  return { ops };
393	}
