395	// --- the forced wake (DESIGN §8) ----------------------------------------------
396	
397	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
398	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
399	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
400	// the member wakes its own items with its own token. The enforcer therefore needs
401	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
402	// the enforcer dispatches and the member executes.
403	//
404	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
405	// tasks, so a caller spanning many members never has to know any one member's pack
406	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
407	// report counts only what it woke reads as coverage it did not have.
408	//
409	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
410	// alone and reported as `already`, never re-woken — an episode boundary dropped on
411	// a live claim is exactly the livelock F18 describes.
412	//
413	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
414	// task that completes closes its item, and the next one appears only at the next
415	// anchor — so between the two there is nothing to wake, and that gap is the common
416	// case rather than an edge: a daily task is missing its item for most of the day.
417	// A force that reported "nothing to wake" there would fail on most members most of
418	// the time, which is precisely what a fleet-wide converge lever must not do. The
419	// minted item is an ordinary standing item — same title, no qualifier: it consumes
420	// the CURRENT occurrence, so the scheduler run does not then create a second one beside it,
421	// and it leaves the next anchor's occurrence untouched.
422	export function planWake(spec, tasks = [], items = []) {
423	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
424	  const wake = []; const create = []; const already = []; const unmatched = [];
425	  for (const id of ids) {
426	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
427	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
428	    if (owners.length !== 1) {
429	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
430	      continue;
431	    }
432	    const owner = owners[0];
433	    const { pack, id: task } = owner;
434	    const item = items.find((i) => {
435	      if (i.state !== 'open') return false;
436	      const parsed = parseWorkItemTitle(i.title);
437	      return parsed && parsed.pack === pack && parsed.task === task;
438	    });
439	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
440	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
441	    wake.push({ id: `${pack}/${task}`, issue: item.number });
442	  }
443	  return { wake, create, already, unmatched };
444	}
