446	// The Context a forced standing item carries. It says the force is the only reason
447	// the item exists, because the executor still evaluates the precondition at pick:
448	// a force that finds no work must roll with its reason on record, not invent work.
449	export const FORCED_WAKE_CONTEXT =
450	  'Minted by a force — this task had no open standing item at the time. The precondition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
451	
452	// The statuses that mean someone already holds this item — decoded, so an item any
453	// engine version filed answers the same. `running-agent` counts: the work is with a
454	// session, and waking would hand a second executor the same item.
455	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
456	
457	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
458	// Reads the work-item list, plans, applies. All GitHub access is the Action's
459	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
460	// said it is out of the recurring work should not pay for the list that proves it.
461	
462	// Every `[claudinite-work]` issue, state=all, via the ISSUES list API — never the
463	// search index (S6/F11: search is eventually consistent, and a family list that
464	// misses a just-created item mints a duplicate standing item). Bounded by the
465	// scheduled families' need for closed history: closed items are only interesting
466	// back to the widest period, so the listing stops once it is past that.
467	export async function listWorkItems(gh, repo, { since = null } = {}) {
468	  const out = [];
469	  for (let page = 1; ; page += 1) {
470	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
471	      + (since ? `&since=${encodeURIComponent(since)}` : '');
472	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
473	    // A page that could not be read is not the end of the list. Breaking on it
474	    // truncates the queue mid-pagination and the run plans against the remainder:
475	    // a standing item whose page never arrived reads as absent, and the run mints a
476	    // second one beside it.
477	    if (status !== 200 || !Array.isArray(json)) {
478	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
479	    }
480	    if (json.length === 0) break;
481	    for (const i of json) {
482	      if (i.pull_request) continue;
483	      if (!(i.title ?? '').startsWith(WORK_PREFIX)) continue;
484	      out.push({
485	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
486	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
487	        updated_at: i.updated_at,
488	      });
489	    }
490	    if (json.length < 100) break;
491	  }
492	  return out;
493	}
