495	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
496	// filtered by label — never the search index, for the same reason the work-item
497	// list is not (S6/F11): a mark this list misses is a request that silently waits an
498	// hour, and one it misses TWICE is a request nobody notices was never picked up.
499	//
500	// The author's push permission comes back with each issue, because adoption gates
501	// the body's parameters on it (§16.7) and the payload's `author_association` is not
502	// that fact: `MEMBER` is any org member whatever their repo permission, and
503	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
504	// leaves the flag `null`, which gates the parameters off — the safe end of a field
505	// that chooses a task, a model, or the right to land a change without review.
506	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
507	  const out = [];
508	  const push = permissionOf ?? (async (login) => {
509	    const res = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
510	    if (res.status === 404) return false;
511	    if (res.status !== 200) return null;
512	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
513	  });
514	  const cache = new Map();
515	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
516	  // comma-separated list selects the issues carrying EVERY name on it — so asking
517	  // for both marks at once asks for issues wearing both, which nothing does. The
518	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
519	  // or in a template, decoded forever like every legacy spelling (§4), and that
520	  // costs a second listing rather than a wider one.
521	  const seen = new Map();
522	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
523	    for (let page = 1; ; page += 1) {
524	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
525	      const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
526	      // A list that could not be READ is not a list that is EMPTY, and the two are
527	      // indistinguishable downstream: adoption simply finds nothing to do and the run
528	      // reports success. Every request then waits for a person to notice, which is
529	      // the one thing this lane exists so nobody has to do.
530	      if (status !== 200 || !Array.isArray(json)) {
531	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
532	      }
533	      if (json.length === 0) break;
534	      for (const i of json) {
535	        if (i.pull_request) continue;
536	        // A filed work item wearing the mark is not a request awaiting adoption: it is
537	        // already an item, and re-adopting one would rewrite its body under the run
538	        // holding it.
539	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
540	        // ANY status means this mark has been adopted — the exactly-once guard (§16.3).
541	        // Filtering here rather than in the plan keeps the permission reads to the
542	        // issues actually awaiting adoption.
543	        if (statusOf(i) !== null) continue;
544	        // An issue wearing both spellings comes back from both listings; it is one
545	        // request, and adopting it twice would rewrite the body of the item the first
546	        // adoption just made.
547	        if (seen.has(i.number)) continue;
548	        const author = i.user?.login ?? null;
549	        if (author && !cache.has(author)) cache.set(author, await push(author));
550	        seen.set(i.number, {
551	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
552	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
553	        });
554	      }
555	      if (json.length < 100) break;
556	    }
557	  }
558	  out.push(...seen.values());
559	  return out;
560	}
