562	// Which `Blocked-by` targets this run still has to read. A target need not be a
563	// work item — a fan-in blocks on whatever its children are — so states come from
564	// the fetched items first and a direct read otherwise, and `known` is what has
565	// already been answered.
566	//
567	// A marked issue's blockers count the same way: adoption decides whether the item
568	// it births is born blocked or ready, and an unread state is never `closed`, so a
569	// missing read delays the request rather than releasing it (§16.11).
570	//
571	// Extracted from `main` so it can be called at all. Nothing else here drives
572	// `main`, whose body is I/O against a live Action, so an identifier it names and
573	// never imports resolves at run time or not at all — and the request half went
574	// three days without executing once, behind an adoption list that was always
575	// empty (#1354).
576	export function blockersToResolve(items, requests, known) {
577	  const wanted = new Set();
578	  for (const i of items) {
579	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
580	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
581	  }
582	  for (const r of requests) {
583	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
584	  }
585	  return wanted;
586	}
