602	
603	  console.log('## Claudinite scheduler run\n');
604	  if (isDormant(config)) {
605	    console.log('- this project declares itself dormant — no items instantiated, readied or reclaimed');
606	    return;
607	  }
608	
609	  const gh = makeGh();
610	  const { tasks, errors } = await discoverTasks(root, config);
611	  for (const e of errors) console.log(`! ${e.what}`);
612	
613	  const now = new Date();
614	  // Closed items matter only back to the widest occurrence guard (a monthly
615	  // task's period); older history can never change a verdict.
616	  const since = new Date(now.getTime() - 40 * 86400e3).toISOString();
617	  const items = await listWorkItems(gh, repo, { since });
618	  const requests = await listMarkedIssues(gh, repo);
