620	  const known = new Map(items.map((i) => [i.number, i.state]));
621	  for (const n of blockersToResolve(items, requests, known)) {
622	    const { status, json } = await gh(`/repos/${repo}/issues/${n}`);
623	    known.set(n, status === 200 ? json?.state ?? null : null);
624	  }
625	
626	  // One comment read per EXECUTING item — never per item in the repo — so the
627	  // reclaim can measure the holder's own silence rather than the issue's.
628	  for (const item of items) {
629	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
630	    item.livenessAt = lastLivenessAt(await listComments(gh, repo, item.number));
