643	  // The anchor-side ask: this task's declared signals, then its precondition —
644	  // any read the scheduler cannot make is an `error`, which fails OPEN in the
645	  // plan. The scheduler stub holds no FLEET_GITHUB_TOKEN (unlike the executor
646	  // workflow), so a fleet task always fails open here and the executor decides.
647	  const { collectSignalsForTask } = await import('./signals.mjs');
648	  const collectFor = collectSignalsForTask({ gh, repo, root, config, defaultBranch });
