677	  // something was marked: `task:origin:ad-hoc` is the entry point, and a label that
678	  // does not exist is one nobody can find in the issue's label picker.
679	  if (tasks.some((t) => `${t.pack}/${t.id}` === REQUEST_TASK_ID)) {
680	    await ensureLabels(gh, repo, QUEUE_LABELS.filter((l) => ORIGIN_LABELS.includes(l.name)));
681	  }
682	
683	  // WHAT THIS RUN ITSELF LEFT READY. The gate below reads the queue back from
684	  // GitHub, and that read is eventually consistent — it can miss an item created
685	  // milliseconds earlier (#1340). The run does not need the read to know what it
686	  // wrote, so every issue it readies is recorded here and counted regardless.
687	  const readied = new Set();
688	
689	  for (const op of ops) {
690	    if (op.kind === 'create') {
691	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
692	      if (res.number) {
693	        if (op.labels.includes(READY)) readied.add(res.number);
694	        console.log(`- created #${res.number} ${op.pack}/${op.task} [${op.labels.join(' ')}]`);
695	      } else console.log(`! could not create the work item for ${op.pack}/${op.task}: ${res.status}`);
696	    } else if (op.kind === 'ready') {
697	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_BLOCKED, READY);
698	      readied.add(op.issue);
699	      console.log(`- readied #${op.issue}`);
700	    } else if (op.kind === 'reclaim') {
701	      // The reclaim comment is also the EPISODE BOUNDARY: every claim before it is
702	      // dead, and arbitrating over dead claims makes one outrank every future live
703	      // claimant — the item then livelocks through reclaim cycles forever (F18).
704	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
705	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_RUNNING_EXECUTOR, op.to);
706	      if (op.to === READY) readied.add(op.issue);
707	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
708	    } else if (op.kind === 'adopt') {
709	      // THE ISSUE IS THE ITEM, so adoption writes to it rather than filing anything:
710	      // the machine block first, the status second. That order is what makes a torn
711	      // adoption safe — a block with no status is re-adopted by the next scheduler
712	      // run (which rewrites it), while a status with no block would name no task.
713	      const res = await gh(`/repos/${repo}/issues/${op.request}`, { method: 'PATCH', body: { body: op.body } });
714	      if (res.status !== 200) {
715	        console.log(`! could not adopt #${op.request}: its body could not be written (${res.status})`);
716	        process.exitCode = 1;
717	        continue;
718	      }
719	      if (op.origin) await addLabel(gh, repo, op.request, op.origin);
720	      await addLabel(gh, repo, op.request, op.status);
721	      await comment(gh, repo, op.request,
722	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
723	        + (op.blockedBy.length
724	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
725	          : '')
726	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
727	        + (op.merge
728	          ? 'The run implements this issue and opens a pull request; it may land that pull request itself only if the diff is narrow, and leaves a wide one for review. '
729	          : 'The run implements this issue and opens a pull request for review — it never merges one. ')
730	        + (op.ungated
731	          ? '\n\nThe `Task:`/`Model:`/`Automerge:` fields in this body were ignored: they are honoured only for an author with push access on this repository, so this run takes the defaults. '
732	          : '')
733	        + `To withdraw the request before it starts, remove the \`${ORIGIN_AD_HOC}\` mark and the status beside it.`);
734	      console.log(`- adopted #${op.request} for ${op.task} (${op.model ?? 'default model'}${op.blockedBy.length ? `, blocked on ${op.blockedBy.map((n) => `#${n}`).join(' ')}` : ''}${op.merge ? ', merge if-narrow' : ''})`);
735	    } else if (op.kind === 'supersede') {
736	      await comment(gh, repo, op.issue, op.reason);
737	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
738	      await closeIssue(gh, repo, op.issue, 'not_planned');
739	      console.log(`- superseded #${op.issue} — #${op.request} was re-marked`);
740	    } else if (op.kind === 'dedupe') {
741	      await comment(gh, repo, op.issue, op.reason);
742	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
743	      await closeIssue(gh, repo, op.issue, 'not_planned');
744	      console.log(`- deduped #${op.issue}`);
745	    } else if (op.kind === 'retire-orphan') {
746	      await comment(gh, repo, op.issue, op.reason);
747	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
748	      await closeIssue(gh, repo, op.issue, 'not_planned');
749	      console.log(`- reaped #${op.issue} — ${op.pack}/${op.task} is not declared at HEAD`);
750	    } else if (op.kind === 'retire-sleeping') {
751	      await comment(gh, repo, op.issue, op.reason);
752	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
753	      await closeIssue(gh, repo, op.issue, 'not_planned');
754	      console.log(`- retired sleeping item #${op.issue} ${op.pack}/${op.task} onto the schedule board`);
755	    } else if (op.kind === 'board') {
756	      if (!boardFetch.readable) {
757	        // Never write what could not be read: a blind create could mint a
758	        // second board. The rows this run derived are re-derived next run.
759	        console.log('! the schedule board could not be listed — skipping its rewrite this run');
760	      } else if (boardFetch.issue) {
761	        const res = await gh(`/repos/${repo}/issues/${boardFetch.issue.number}`, {
762	          method: 'PATCH',
763	          body: { body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }) },
764	        });
765	        console.log(res.status === 200
766	          ? `- schedule board #${boardFetch.issue.number} updated (${op.rows.length} row(s))`
767	          : `! could not update schedule board #${boardFetch.issue.number}: ${res.status}`);
768	      } else {
769	        const res = await createIssue(gh, repo, {
770	          title: scheduleBoardTitle(),
771	          body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }),
772	          labels: [],
773	        });
774	        console.log(res.number
775	          ? `- schedule board created as #${res.number} (${op.rows.length} row(s))`
776	          : `! could not create the schedule board: ${res.status}`);
777	      }
778	    }
779	  }
780	
781	  if (!ops.length) console.log('- nothing to do: every task has its standing item, nothing is due, nothing is marked, no claim is dead');
782	
783	  // The forced wake, last: an item this run just instantiated is wakeable in the
784	  // same run, so a force never has to be pressed twice. The drain job that follows
785	  // picks up whatever this readies.
786	  const spec = process.env.CLAUDINITE_WAKE ?? '';
787	  if (spec.trim()) {
788	    const { wakeItem } = await import('./create-work-item.mjs');
789	    // Re-read: the ops above may have created or readied the very items named.
790	    const current = await listWorkItems(gh, repo, { since });
791	    const { wake, create, already, unmatched } = planWake(spec, tasks, current);
792	    for (const w of wake) {
793	      const res = await wakeItem(gh, repo, w.issue);
794	      if (res.ok) readied.add(w.issue);
795	      console.log(res.ok ? `- woke #${w.issue} ${w.id}` : `! could not wake #${w.issue} ${w.id}: ${res.error}`);
796	    }
797	    if (create.length) await ensureLabels(gh, repo, QUEUE_LABELS);
798	    for (const c of create) {
799	      const res = await createIssue(gh, repo, {
800	        title: workItemTitle({ pack: c.pack, task: c.task }),
801	        body: workItemBody({ taskPath: c.taskPath, context: [FORCED_WAKE_CONTEXT] }),
802	        // A forced mint stands in for the occurrence a schedule would have filed, so
803	        // it wears the same origin: the task IS on a calendar, and this item is its
804	        // current occurrence (§8).
805	        labels: [ORIGIN_PLANNED, READY],
806	      });
807	      if (res.number) {
808	        readied.add(res.number);
809	        console.log(`- created #${res.number} ${c.id} (forced: it had no open standing item)`);
810	      } else { console.log(`! could not create a work item for ${c.id}: ${res.status}`); process.exitCode = 1; }
811	    }
812	    for (const a of already) console.log(`- ${a.id} is already in flight on #${a.issue} — left alone`);
813	    for (const u of unmatched) console.log(`! nothing woken for "${u.id}": ${u.why}`);
814	    // A force that woke nothing is a failed force, and a green run saying so in a
815	    // log line is how it goes unnoticed by the fleet lever that pressed it.
816	    if (unmatched.length) process.exitCode = 1;
817	  }
818	
819	  // LAST, AFTER THE WAKE: whether this run leaves anything for an executor to do.
820	  await announcePickable(gh, repo, tasks, readied);
821	}
822	
823	// THE DRAIN GATE (§15.30). Every workflow run is a billed invocation whatever it
824	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
825	// executor only when this run's parting look at the queue found something
826	// pickable. On a quiet repo that is the difference between 24 executor runs a day
827	// and none.
828	//
829	// This is the run's LAST act, after the forced wake: a wake readies items, and a
830	// look taken before it would send the hour's forced work to the next cron fire.
831	//
832	// The delivery is unweakened by the gate. A label event may be lost, and what a
833	// lost event would have delivered is exactly what this look sees — the queue
834	// itself, read live, by the same pick rule the executor applies. Where the
835	// output cannot be written (a run outside Actions, an older member workflow that
836	// maps no output) the drain job's own default decides, and the run says which
837	// happened rather than going quiet about it.
838	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
839	// this run itself readied is the other, and the second needs no confirmation —
840	// GitHub's issue list is eventually consistent, so an item created milliseconds
841	// earlier can be absent from it (#1340). Trusting the read alone left a forced
842	// `update` sitting `task:ready` until the next cron fire on three members at once.
843	// Ordering stays the executor's job: this only decides whether to start one.
844	export function pickableCount(open, readiedThisRun = [], opts = {}) {
845	  const listed = pickOrder(open, opts).map((i) => i.number);
846	  return new Set([...listed, ...readiedThisRun]).size;
847	}
848	
849	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
850	  const { listOpenWorkItems } = await import('./read.mjs');
851	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
852	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
853	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
854	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
855	    frequencyOf: (id) => byId.get(id)?.decl?.frequency ?? null,
856	    pathTo: (p) => byPath.get(p) ?? null,
857	  });
858	  console.log(pickable
859	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
860	    : '- nothing pickable — no executor is dispatched this run');
861	  const out = process.env.GITHUB_OUTPUT;
862	  if (!out) return;
863	  const { appendFileSync } = await import('node:fs');
864	  appendFileSync(out, `pickable=${pickable ? 'true' : 'false'}\n`);
865	}
866	
867	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
868	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
869	// point that must be able to start the same run without being this module.
870	export { main as runSchedulerRun };
871	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
872	  main().catch((e) => { console.error(e); process.exit(1); });
873	}
874	
875	export { parseWorkItemTitle };
876

